    /** @brief 这行的底色偏深 ⇒ 次级文字（副标题/右值）用浅色而不是 MUTE。
     *  @details 选中块也是一块深底，两者共用同一个开关：选中时由 helm_widget.c 按 mix 置位。 */
    bool bg_dark;
