lv_obj_t * helm_mlist_create(lv_obj_t * parent);
/** @brief 关滑动光标并擦掉脏区。关页/淡出前调用，避免局部刷新把橙色条留在下一页。 */
void helm_mlist_cursor_off(lv_obj_t * list);
/** @brief 光标立刻落到 idx（进页/重建列表，不做滑动）。 */
