/** @brief 子页进入。dir>0 从右，dir<0 从左。 */
void helm_obj_enter(lv_obj_t * obj, int dir);
/** @brief 按键确认：行下压回弹（弹窗/dock）。 */
void helm_obj_press(lv_obj_t * obj);

/**
 * @file bicycle_config.h
 * @brief 自行车 UI 配置（轨迹容量、PSRAM 规划、导航参数）。
 */

#ifndef BICYCLE_CONFIG_H
#define BICYCLE_CONFIG_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* -------------------------------------------------------------------------
 * Track / km-marker capacity (compile-time layout + PSRAM planning)
 *
 * Single session: cumulative km badges 1, 2, … (no upper stop).
 * Map stores BICYCLE_KM_MARKER_MAX slots; km 1…N use slot N-1, then km N+1
 * wraps and overwrites slot 0 like a ring buffer.
 * On-screen track polyline: current lap only (cleared on lap closure); pts[]
 * ring holds up to BICYCLE_MAX_SESSION_KM at BICYCLE_TRACK_POINT_MIN_DIST_M
 * spacing (~50k points @ 3 m).
 * PSRAM arena: draw decimation buffer + track points (+ slack).
 * ------------------------------------------------------------------------- */

#ifndef BICYCLE_MAX_SESSION_KM
#define BICYCLE_MAX_SESSION_KM             150u
#endif

#ifndef BICYCLE_TRACK_POINT_MIN_DIST_M
#define BICYCLE_TRACK_POINT_MIN_DIST_M     3.0
#endif

#ifndef BICYCLE_TRACK_DRAW_CAP
#define BICYCLE_TRACK_DRAW_CAP             384u
#endif

/** 地图上公里标记环槽上限（150 → 150 km 后从 slot 0 覆盖）。 */
#define BICYCLE_KM_MARKER_MAX              (BICYCLE_MAX_SESSION_KM)

/** pts[] 可表示的最大单圈屏幕距离（米）。 */
#define BICYCLE_MAX_LAP_DISPLAY_M \
    ((uint32_t)(BICYCLE_MAX_SESSION_KM) * 1000u)

/** 地图会话显示的轨迹点环容量。 */
#define BICYCLE_TRACK_POINT_CAP \
    ((uint16_t)(((BICYCLE_MAX_LAP_DISPLAY_M) \
        + (uint32_t)(BICYCLE_TRACK_POINT_MIN_DIST_M) - 1u) \
        / (uint32_t)(BICYCLE_TRACK_POINT_MIN_DIST_M)))

/** 结构体布局大小（arena 预算；须与 vmap_track.c 一致）。 */
#define BICYCLE_TRACK_PT_BYTES             12u
#define BICYCLE_TRACK_DRAW_PT_BYTES        12u
#define BICYCLE_TRACK_ARENA_SLACK_BYTES    4096u

/** 每公里轨迹环记录的 GNSS 点数（ceil(1000 / min_dist_m)）。 */
#define BICYCLE_TRACK_POINTS_PER_KM \
    ((uint32_t)(1000u + (uint32_t)(BICYCLE_TRACK_POINT_MIN_DIST_M) - 1u) \
        / (uint32_t)(BICYCLE_TRACK_POINT_MIN_DIST_M))

/** max_session_km 每增加 1 km 的 PSRAM arena 增量（仅 pts[]；draw cap 固定）。 */
#define BICYCLE_TRACK_PSRAM_BYTES_PER_KM \
    ((size_t)(BICYCLE_TRACK_POINTS_PER_KM) * (size_t)BICYCLE_TRACK_PT_BYTES)

#define BICYCLE_TRACK_ARENA_BYTES \
    ((size_t)(BICYCLE_TRACK_DRAW_CAP) * (size_t)BICYCLE_TRACK_DRAW_PT_BYTES \
     + (size_t)(BICYCLE_TRACK_POINT_CAP) * (size_t)BICYCLE_TRACK_PT_BYTES \
     + (size_t)BICYCLE_TRACK_ARENA_SLACK_BYTES)

#include "vmap/vmap_track.h"
#include "vmap/vmap_style.h"

typedef struct {
    vmap_track_lap_config_t lap;
    /** 地图轨迹上公里标记间距（米）。 */
    double km_marker_interval_m;
    /** 屏幕单圈/轨迹点预算（km，<= BICYCLE_MAX_SESSION_KM）。
     *  PSRAM 轨迹环：每 km +BICYCLE_TRACK_PSRAM_BYTES_PER_KM
     *  （默认 3 m 间距 → 334 pts/km × 12 B ≈ 4.0 KiB/km；150 km ≈ 586 KiB
     *  pts[]，另加固定 draw 抽稀 ~4.6 KiB + 4 KiB slack）。
     *  km 标记槽为 vmap_track 中独立固定环（非按 km 增长）。 */
    uint16_t max_session_km;
    /** 地图 km 标记环槽数（默认 BICYCLE_KM_MARKER_MAX）。 */
    uint16_t km_marker_max;
    /** 屏幕单圈轨迹点上限（<= BICYCLE_TRACK_POINT_CAP）。 */
    uint16_t track_point_cap;
    /** pts 超过 track_point_cap 时折线抽稀采样上限。 */
    uint16_t track_draw_cap;
    /** 记录 GNSS 点的最小间距（米）。 */
    double track_point_min_dist_m;
    /** 自动重路由偏航距离（米）：反骑过久或过路口后偏航。 */
    double nav_off_route_m;
    bool record_on_start;
    uint32_t gnss_update_ms;
    float gnss_sim_speed_kph;
    /** `nav sim` 规划成功后的沿路线速度（km/h）。 */
    float nav_sim_speed_kph;
    const char * gpx_path;
    vmap_style_id_t map_style;
} bicycle_config_t;

/**
 * @brief 自行车 config reset defaults。
 */
void bicycle_config_reset_defaults(void);
/**
 * @brief 自行车 config。
 */
const bicycle_config_t * bicycle_config(void);
/**
 * @brief 自行车 config get。
 * @return 请求的值。
 */
void bicycle_config_get(bicycle_config_t * out);
/**
 * @brief 自行车 config set。
 */
void bicycle_config_set(const bicycle_config_t * cfg);
/**
 * @brief 自行车 config apply。
 */
void bicycle_config_apply(void);

/**
 * @brief 自行车 config max session km。
 */
uint16_t bicycle_config_max_session_km(void);
/**
 * @brief 自行车 config km marker max。
 */
uint16_t bicycle_config_km_marker_max(void);
/**
 * @brief 自行车 config track point cap。
 */
uint16_t bicycle_config_track_point_cap(void);
/**
 * @brief 自行车 config track draw cap。

/**
 * @file map_page.h
 * @brief 实况地图页。
 *
 * 地图画布叠层（底 → 顶）：底图 → 导航线 → 标签 → REC 线 → REC 数字。
 * 定位箭头是 LVGL 控件，在画布之上。
 */

#ifndef MAP_PAGE_H
#define MAP_PAGE_H

#include "vmap/vmap_view.h"
#include "vmap/vmap_config.h"
#include "vmap/vmap_style.h"
#include "lv_pm_core.h"
#include "lvgl/lvgl.h"

#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef struct map_page map_page_t;

/**
 * @brief 向 lv_pm 注册 LiveMap（`lvgl_page_init` 调用）。
 */
void live_map_page_register(void);
/** @brief 已注册的 LiveMap 页描述符（开机静默 push 用）。 */
lv_pm_page_t live_map_page_def(void);
/**
 * @brief 当前 LiveMap 实例。
 * @return 尚未 `create` 则为 NULL。
 */
map_page_t * live_map_page_instance(void);

/**
 * @brief 在 @p parent 上创建地图页（画布、箭头、Helm chrome）。
 * @param parent lv_pm 页面根。
 * @return 实例；失败为 NULL。
 * @note `boot_deferred` 时只建空壳，vmap 留给 `map_page_boot_begin_load()`。
 */
map_page_t * map_page_create(lv_obj_t * parent);
/**
 * @brief 销毁地图页（关 GPX、卸瓦片、删 LVGL 对象）。
 * @param page 实例；可为 NULL。
 */
void map_page_destroy(map_page_t * page);
/**
 * @brief 把当前画布 / 轨迹打到调试缓冲（NSH snap）。
 * @param page 实例。
 */
void map_page_debug_snap(map_page_t * page);

/** @brief 循环主题（classic → nav → outdoor）并刷新 chrome。 */
bool map_page_cycle_style(map_page_t * page);
/**
 * @brief 当前主题名。
 * @param page 未使用，可为 NULL。
 */
const char * map_page_style_name(const map_page_t * page);
/**
 * @brief 按样式 id 切主题。
 * @param page LiveMap。
 * @param id   `vmap_style_id_t`。
 */
bool map_page_set_style(map_page_t * page, vmap_style_id_t id);
/**
 * @brief 按名字切主题（`classic` / `nav` / `outdoor`）。
 */
bool map_page_set_style_by_name(map_page_t * page, const char * name);
/**
 * @brief 按当前主题重刷 chrome / 箭头（不一定重栅格）。
 */
void map_page_redraw(map_page_t * page);

/**
 * @brief 显示/隐藏定位方向箭头（骑行者箭头）。
 * @param page LiveMap。
 * @param visible true 露出箭头；false 藏起来。
 * @note 平时由导航路径自己管（`nav_stop` / `nav_from_gpx` 会打开，"只看轨迹"的
 *       `map_page_show_gpx()` 会关掉）。规划导航（`map_page_nav_plan_begin()` /
 *       `map_page_nav_trip_plan()`）起航时也会显式打开并置顶，避免上一轮"回放/只看轨迹"
 *       留下的隐藏态带进坐标点导航（2026-10-18 修复）。
 */
void map_page_set_arrow_visible(map_page_t * page, bool visible);

/** @brief 在 LVGL 线程应用缩放 ctl：in/out/reset/z,N/s,F；非法时返回 false。 */
bool map_page_apply_zoom_cmd(map_page_t * page, const char * arg);
/** @brief 航向朝上开关 ctl：on/off；非法时返回 false。 */
bool map_page_apply_rot_cmd(map_page_t * page, const char * arg);
/**
 * @brief 把当前 zoom/scale 写进 ctl 状态，供 NSH 查询。
 */
void map_page_sync_zoom_state(map_page_t * page);

/** @brief UsbTransfer 覆盖 LiveMap：暂停地图 UI；GNSS/轨迹录制继续。不关瓦片句柄。 */
void map_page_pause_for_cover(map_page_t * page);

/** @brief UsbTransfer pop 后恢复地图渲染（从 RAM 重绘轨迹）。 */
void map_page_resume_after_cover(map_page_t * page);

/** @brief MTP 会话结束（拔线）后重载地图瓦片。 */
void map_page_reload_storage(map_page_t * page);
/** @brief 关闭打开的地图分片句柄（MTP 静默）；保留画布与 RAM 缓存。 */
void map_page_release_storage(map_page_t * page);

#if VMAP_ROUTE_ENABLE
#include "vmap/vmap_route_trip.h"
/** @brief 规划路线。可显式传入 from_lon/lat，或 NAN 表示调用时冻结 GNSS。 */
bool map_page_nav_plan(map_page_t * page, double from_lon, double from_lat,
    double to_lon, double to_lat);
/** @brief 规划路线后按 VMAP_NAV_SIM_SPEED_KPH 沿折线驱动。 */
bool map_page_nav_plan_sim(map_page_t * page, double from_lon, double from_lat,
    double to_lon, double to_lat);
/** @brief 多途经点：当前坐标不算，一次规划下一点与下下一点；过点后静默补点。 */
bool map_page_nav_trip_plan(map_page_t * page,
    const vmap_route_waypoint_t * waypoints, uint32_t count);
/** @brief 设置多点导航显示名；当前 leg 名称用于顶部“去 xxx”。 */
void map_page_nav_trip_set_names(map_page_t * page,
    const char * const * names, uint32_t count);
/**
 * @brief 就近规划：扫最近的 GPX 点或途经点，以该点为目标向后重新规划。
 * @return 已提交/已对齐为 true；无定位、已到终点或无法规划为 false。
 */
bool map_page_nav_plan_nearest(map_page_t * page);
/**
 * @brief 停止导航并清路线叠层。
 */
void map_page_nav_stop(map_page_t * page);
#endif

/**
 * @brief Startup 进度页内准备地图文件，不解码或绘制瓦片。
 * @param page LiveMap 实例；NULL 则先 `boot_begin_load`。
 * @return 文件准备流程已经结束为 true；资源尚不可用时返回 false。
 * @details 加载 catalog 和启动坐标 region pack。Canvas 只清零并隐藏，
 *          首帧在 LiveMap 淡入完成后开始。
 */
bool map_page_boot_prepare(map_page_t * page);

/**
 * @brief 延迟 `map_page_create` 到 Startup 白屏之后（boot 序列）。
 * @param deferred true：先进空壳；false：create 时立刻 set_view。
 */
void map_page_set_boot_deferred(bool deferred);

/**
 * @brief 在已进栈的 LiveMap 空壳上创建 vmap（logo 变白后调用）。
 * @return 已有实例或创建成功为 true。
 * @note 创建后 `covered=true`，所有 LiveMap timer 保持暂停。
 */
bool map_page_boot_begin_load(void);

